package main

import (
	"bufio"
	"fmt"
	"os"
)

func findLissPos() int {
	scanner := bufio.NewScanner(os.Stdin)

	scanner.Scan()
	stones := scanner.Text()

	scanner.Scan()
	instructions := scanner.Text()

	curPos := 0
	for i := 0; i < len(instructions); i++ {
		if curPos < len(stones) && stones[curPos] == instructions[i] {
			curPos++
		}
	}

	return curPos + 1
}

func main() {
	fmt.Print(findLissPos())
}

